// #772789 (db1dba9783e89397fd772789) «iOS/Web - «תזכורות מהירות» ממשיך להציג תזכורת לתפילה שהמשתמש כבר התפלל ורשם»
// — עבר QA 25.10.2026 (iPhone 17, iOS 26.6.1, TestFlight 1.0.0 (20) + OTA новее dc2b259, вход клиента).
// מה רצוי (тикет; F-47 описание/AC1/AC5 + решение владельца продукта 20.10): после записи молитвы напоминание о ней в «תזכורות מהירות»
//   не показывается; прочие (הנחת תפילין и т.д.) остаются; повторная запись той же молитвы в тот же день остаётся возможной.
// Факт 25.10 (session-2026-10-25.json, снимки .qa/screenshots/772789-before/finish/after/after-restart.png): 12:00 — «מנחה / אפשר להתפלל
//   עכשיו, עד 16:58» и «הנחת תפילין / אל תשכח להניח היום עד השקיעה» → «התחל תפילה» → «סיים תפילה» → «כל הכבוד! / סיימת את תפילת מנחה
//   בהצלחה» → «חזרה למסך ראשי» → מנחה исчезла, הנחת תפילין осталась, «תפילות אחרונות» первая — «מנחה · י״ד חשון · 12:01»; после 2 холодных
//   стартов — так же. Повтор: «התפילה כבר נרשמה היום» «… כבר נרשמה ביום העברי הזה. לרשום אותה שוב?» + «ביטול»/«רשום שוב» (решение 20.10).
// Бриф .qa/research/db1dba97.md. Кейс .qa/tests/reminders/RM-11-quick-reminders-hide-recorded-prayer.md. Веб-пара:
//   .qa/e2e/tests/reminders/rm-11-quick-reminders-hide-recorded-prayer-db1dba97.spec.ts.
// @time: нужна молитва, чьё окно открыто сейчас и которая сегодня ещё не записана (её карточка «אפשר להתפלל עכשיו» видна) — иначе skip.
// @data: добавляет запись молитвы в аккаунт (необратимо) — только с QA_RECORD_PRAYER=1 (как RD-01c/RD-02b). «רשום שוב» не нажимаем.
// Правила: кнопки — по имени, без координат и фиксированных пауз; «התזכורות כבויות…» на главной — skip (тумблер не трогаем).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches } from '../../helpers/ui.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { goHome, button, recordAllowed } from '../_lib/readiness-1910.ts';
import { homeHebrewDate } from '../_lib/app-1310b.ts';
import {
  coldStart, saveShot, quickReminderCards, qrHas, qrOpenPrayer, qrOtherTitles, openPrayerForRecord, scrollAndFinish,
  confirmFinishWindow, recentFirstRow, todayCount, QR_OFF, QR_TEFILLIN, QR_TEFILLIN_TEXT, QR_REPEAT_TEXT,
  RM_REPEAT_TITLE, RM_REPEAT_AGAIN, type QrPrayer,
} from '../_lib/app-2510.ts';

const RECENT_WHEN = /^[א-ת״׳' ]+ · \d{2}:\d{2}(:\d{2})?$/;
let recorded: QrPrayer | null = null;

describe('«תזכורות מהירות» — записанная молитва скрыта (#772789)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('RM-11a Запись молитвы с открытым окном → её карточка исчезает из «תזכורות מהירות», прочие на месте, «תפילות אחרונות» и «תפילות היום» +1; держится после 2 холодных стартов #772789 @time @data', async function () {
    if (!recordAllowed()) skipWith(this, 'добавляет запись молитвы (необратимо) — запуск с QA_RECORD_PRAYER=1');
    await goHome();
    if (await shown(byText(QR_OFF))) skipWith(this, '«תזכורות במערכת» выключен — включить в профиле и повторить');

    // 1. До записи: карточка молитвы с открытым окном («<молитва> · אפשר להתפלל עכשיו, עד HH:MM»).
    const before = await quickReminderCards();
    console.log(`[RM-11a] карточки до: ${JSON.stringify(before)}`);
    const open = qrOpenPrayer(before);
    if (!open) skipWith(this, 'сейчас нет молитвы с открытым окном, не записанной сегодня (карточки «אפשר להתפלל עכשיו» нет) — повторить в окне מנחה/ערבית/שחרית');
    const prayer = open!.prayer;
    expect(open!.card).toMatch(/עד \d{1,2}:\d{2}/);                    // F-47 AC3: заголовок + пояснение с временем окончания
    const others = qrOtherTitles(before);                               // напр. «הנחת תפילין», «לראש חודש», «תאריך חשוב»
    if (qrHas(before, QR_TEFILLIN)) expect(before.some((c) => c.includes(QR_TEFILLIN_TEXT))).toBe(true);
    const today0 = await todayCount();
    await saveShot('772789-q19-before.png');

    // 2. «התחל תפילה» (или каталог, если ближайшая — другая) → «סיים תפילה» → «כל הכבוד!» → «חזרה למסך ראשי».
    const how = await openPrayerForRecord(prayer);
    console.log(`[RM-11a] ${prayer} открыта: ${how}`);
    const r = await scrollAndFinish();
    if (r === 'already') {
      await (await button('ביטול')).click();
      throw new Error(`«${prayer}» уже записана сегодня, но её карточка «אפשר להתפלל עכשיו» была в «תזכורות מהירות» — расхождение с #772789 (сверить вручную)`);
    }
    recorded = prayer;
    await saveShot('772789-q19-finish.png');
    await confirmFinishWindow(prayer);

    // 3. Главная: карточки записанной молитвы нет, прочие остались; «תפילות אחרונות» — первая эта молитва; «תפילות היום» +1.
    const after = await quickReminderCards();
    console.log(`[RM-11a] карточки после: ${JSON.stringify(after)}`);
    expect({ prayer, shown: qrHas(after, prayer) }).toEqual({ prayer, shown: false });          // מה רצוי
    for (const t of others) expect({ t, kept: qrHas(after, t) }).toEqual({ t, kept: true });       // «שאר התזכורות ממשיכות להופיע»
    const recent = await recentFirstRow();
    expect(recent?.prayer).toBe(prayer);                                                          // S-10 AC5
    expect(recent?.when ?? '').toMatch(RECENT_WHEN);
    expect(await todayCount()).toBe(today0 + 1);                                                  // S-10 AC3: тот же источник
    await saveShot('772789-q19-after.png');

    // 4. Два холодных старта — карточка не возвращается, прочие на месте.
    for (let i = 1; i <= 2; i++) {
      await coldStart(`RM-11a холодный старт ${i}`);
      const again = await quickReminderCards();
      expect({ i, prayer, shown: qrHas(again, prayer) }).toEqual({ i, prayer, shown: false });
      for (const t of others) expect({ i, t, kept: qrHas(again, t) }).toEqual({ i, t, kept: true });
      expect((await recentFirstRow())?.prayer).toBe(prayer);
    }
    await saveShot('772789-q19-after-restart.png');
  });

  it('RM-11b Повторная запись той же молитвы: «התפילה כבר נרשמה היום» «… כבר נרשמה ביום העברי הזה. לרשום אותה שוב?» с «ביטול»/«רשום שוב»; «ביטול» — счётчик и «תזכורות מהירות» без изменений #772789 @time @prod-safe', async function () {
    // Без записи («רשום שוב» не нажимаем). Молитва — записанная в RM-11a, иначе первая строка «תפילות אחרונות», если она записана сегодня.
    await goHome();
    const today0 = await todayCount();
    if (today0 === 0) skipWith(this, 'сегодня записей нет — нечего повторять');
    let prayer = recorded as QrPrayer | null;
    if (!prayer) {
      // Без RM-11a: первая строка «תפילות אחרונות» должна быть СЕГОДНЯШНЕЙ (день+месяц = еврейская дата заголовка главной),
      // иначе «סיים תפילה» запишет новую молитву (тест только читает).
      const recent = await recentFirstRow();
      if (!recent) skipWith(this, 'нет блока «תפילות אחרונות»');
      const head = await homeHebrewDate();
      const sameDay = recent!.when.startsWith(`${head.day} ${head.month} · `);
      console.log(`[RM-11b] первая строка «${recent!.prayer} · ${recent!.when}», сегодня «${head.full}»`);
      if (!sameDay) skipWith(this, 'первая запись «תפילות אחרונות» не сегодняшняя — повтор проверить после RM-11a');
      prayer = recent!.prayer as QrPrayer;
    }

    await openPrayerForRecord(prayer);
    expect(await scrollAndFinish()).toBe('already');
    await expect(byTextContains(RM_REPEAT_TITLE)).toBeDisplayed();
    await expect(byTextContains(QR_REPEAT_TEXT)).toBeDisplayed();
    expect(await shown(button(RM_REPEAT_AGAIN))).toBe(true);                                      // повтор разрешён (решение 20.10)
    expect(await shown(button('ביטול'))).toBe(true);
    await (await button('ביטול')).click();
    await expect(byTextContains(RM_REPEAT_TITLE)).not.toBeDisplayed({ wait: 10000 });
    await expect(byTextMatches('\\d+ מתוך \\d+')).toBeExisting();                                // остались в молитве

    await goHome();
    expect(await todayCount()).toBe(today0);
    const cards = await quickReminderCards();
    expect({ prayer, shown: qrHas(cards, prayer) }).toEqual({ prayer, shown: false });
  });
});
